-- สัปดาห์ 7–10 ของ 2026/27 ใช้ player_gameweek_stats.csv เฉพาะสัปดาห์ที่แต่ละทีมเล่นหนึ่งนัด
-- ข้อมูลยิง/จ่ายรายนัด 2026/27: https://github.com/olbauday/FPL-Core-Insights/tree/main/data/2026-2027
-- สนาม: https://www.premierleague.com/en/news/4725666/all-you-need-to-know-about-the-20-premier-league-stadiums
-- ตัวอย่างหลังนำเข้า:
-- SELECT * FROM pl_history.v_player_season WHERE season_id=2026 ORDER BY goals DESC, player_name LIMIT 10;
-- SELECT * FROM pl_history.v_team_season WHERE season_id=2025 ORDER BY wins DESC;
-- SELECT * FROM pl_history.v_match_results WHERE status='completed' ORDER BY kickoff_utc DESC LIMIT 10;
-- SELECT * FROM pl_history.v_match_results WHERE status='scheduled' ORDER BY kickoff_utc LIMIT 10;
BEGIN;
CREATE SCHEMA IF NOT EXISTS pl_history;
SET LOCAL search_path = pl_history, pg_catalog;

CREATE TABLE IF NOT EXISTS seasons (
    season_id integer PRIMARY KEY, label text NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS teams (
    team_id integer PRIMARY KEY, team_name text NOT NULL, short_name text NOT NULL, city text NOT NULL
);
CREATE TABLE IF NOT EXISTS team_seasons (
    season_id integer REFERENCES seasons, team_id integer REFERENCES teams,
    home_stadium text NOT NULL, PRIMARY KEY (season_id, team_id)
);
CREATE TABLE IF NOT EXISTS players (
    player_id integer PRIMARY KEY, player_name text NOT NULL, display_name text NOT NULL, birth_date date
);
CREATE TABLE IF NOT EXISTS matches (
    match_id integer PRIMARY KEY, season_id integer NOT NULL REFERENCES seasons,
    matchweek integer, match_date date NOT NULL, kickoff_utc timestamptz, home_team_id integer NOT NULL,
    away_team_id integer NOT NULL, status text NOT NULL CHECK (status IN ('completed','scheduled','live')),
    home_goals integer, away_goals integer, ht_home_goals integer, ht_away_goals integer,
    home_shots integer, away_shots integer, home_shots_on_target integer, away_shots_on_target integer,
    UNIQUE (season_id,home_team_id,away_team_id), CHECK (home_team_id <> away_team_id),
    FOREIGN KEY (season_id, home_team_id) REFERENCES team_seasons,
    FOREIGN KEY (season_id, away_team_id) REFERENCES team_seasons
);
CREATE TABLE IF NOT EXISTS player_match_stats (
    match_id integer REFERENCES matches, player_id integer REFERENCES players, team_id integer NOT NULL REFERENCES teams,
    position text NOT NULL, minutes integer NOT NULL CHECK (minutes > 0), goals integer NOT NULL,
    assists_fpl integer NOT NULL, own_goals integer NOT NULL, yellow_cards integer NOT NULL,
    red_cards integer NOT NULL, saves integer NOT NULL, shots integer, shots_on_target integer,
    passes_completed integer, pass_accuracy_pct numeric, rating_10 numeric CHECK (rating_10 BETWEEN 0 AND 10),
    PRIMARY KEY (match_id, player_id)
);

ON CONFLICT (season_id) DO NOTHING;

