CREATE OR REPLACE VIEW v_match_results AS
SELECT m.*, s.label AS season, h.team_name AS home_team, a.team_name AS away_team, ts.home_stadium
FROM matches m JOIN seasons s USING (season_id)
JOIN teams h ON h.team_id=m.home_team_id JOIN teams a ON a.team_id=m.away_team_id
JOIN team_seasons ts ON ts.season_id=m.season_id AND ts.team_id=m.home_team_id;

CREATE OR REPLACE VIEW v_player_season AS
SELECT m.season_id, s.label AS season, p.player_id, p.player_name, p.display_name, p.birth_date,
       COUNT(*) AS appearances, SUM(x.minutes) AS minutes, SUM(x.goals) AS goals,
       SUM(x.assists_fpl) AS assists_fpl, SUM(x.yellow_cards) AS yellow_cards,
       SUM(x.red_cards) AS red_cards, SUM(x.saves) AS saves,
       CASE WHEN COUNT(x.shots)=COUNT(*) THEN SUM(x.shots) END AS shots,
       CASE WHEN COUNT(x.shots_on_target)=COUNT(*) THEN SUM(x.shots_on_target) END AS shots_on_target,
       COUNT(x.shots) AS appearances_with_shots, AVG(x.rating_10) AS average_rating
FROM player_match_stats x JOIN players p USING (player_id) JOIN matches m USING (match_id)
JOIN seasons s USING (season_id) WHERE m.status='completed'
GROUP BY m.season_id,s.label,p.player_id,p.player_name,p.display_name,p.birth_date;

CREATE OR REPLACE VIEW v_team_season AS
WITH team_games AS (
    SELECT season_id,home_team_id AS team_id,home_goals AS gf,away_goals AS ga FROM matches WHERE status='completed'
    UNION ALL
    SELECT season_id,away_team_id,away_goals,home_goals FROM matches WHERE status='completed'
)
SELECT g.season_id,s.label AS season,t.team_id,t.team_name,COUNT(*) AS played,
       SUM(CASE WHEN gf>ga THEN 1 ELSE 0 END) AS wins,SUM(CASE WHEN gf=ga THEN 1 ELSE 0 END) AS draws,
       SUM(CASE WHEN gf<ga THEN 1 ELSE 0 END) AS losses,SUM(gf) AS goals_for,SUM(ga) AS goals_against
FROM team_games g JOIN teams t USING (team_id) JOIN seasons s USING (season_id)
GROUP BY g.season_id,s.label,t.team_id,t.team_name;
COMMIT;
SELECT s.label AS season, COUNT(*) FILTER (WHERE status='completed') AS completed,
       COUNT(*) FILTER (WHERE status='scheduled') AS scheduled
FROM pl_history.matches m JOIN pl_history.seasons s USING (season_id)
GROUP BY s.season_id,s.label ORDER BY s.season_id DESC;
